// mixtype
// Generated by instruction
const N: usize = 100;
const X: usize = 100;
const MD: u64 = 1000000007;

fn power(a: i32, k: i32) -> u64 {
    if k == 0 {
        return 1;
    }
    let mut p = power(a, k >> 1);
    p = p * p % MD;
    if k & 1 != 0 {
        p = p * a as u64 % MD;
    }
    p
}

fn main() {
    use std::io::{self, Write};
    let mut input = String::new();
    io::stdin().read_line(&mut input).unwrap();
    let mut parts = input.split_whitespace();
    let n: usize = parts.next().unwrap().parse().unwrap();
    let x: usize = parts.next().unwrap().parse().unwrap();
    let cc: Vec<char> = parts.next().unwrap().chars().collect();

    if x == 0 {
        println!("{}", if n == 1 && cc[0] == '0' { 1 } else { 0 });
        return;
    }

    let mut ff = vec![0; X + 1];
    let mut ds = vec![vec![vec![0; N + 1]; N]; X + 1];
    let mut dp = vec![vec![0; N]; X + 1];
    let mut dq = vec![vec![0; N]; X + 1];
    let mut dr = vec![0; X + 1];

    ff[0] = 1;
    ff[1] = 1;
    for i in 2..=x {
        ff[i] = (ff[i - 1] + ff[i - 2]) % (MD as usize - 1);
    }
    for i in 0..=x {
        ff[i] = power(2, ff[i] as i32);
    }
    for l in 0..n {
        ds[0][l][l] = 1;
        ds[1][l][l] = 1;
        ds[0][l][l + 1] = if cc[l] == '0' { 1 } else { 0 };
        ds[1][l][l + 1] = if cc[l] == '1' { 1 } else { 0 };
    }
    for i in 2..=x {
        for l in 0..n {
            for r in l..n {
                let mut z = 0;
                for m in l..=r {
                    z = (z + ds[i - 1][l][m] as u64 * ds[i - 2][m][r] as u64) % MD;
                }
                ds[i][l][r] = z;
            }
        }
    }
    if n > 1 {
        dp[0][n - 1] = ds[0][n - 1][n];
        dp[1][n - 1] = ds[1][n - 1][n];
        for i in 2..=x {
            for l in 1..n {
                let mut z = dp[i - 1][l] as u64 * ff[i - 2] % MD;
                for m in l..n {
                    z = (z + ds[i - 1][l][m] as u64 * dp[i - 2][m] as u64) % MD;
                }
                dp[i][l] = z;
            }
        }
        dq[0][1] = ds[0][0][1];
        dq[1][1] = ds[1][0][1];
        for i in 2..=x {
            for r in 1..n {
                let mut z = ff[i - 1] * dq[i - 2][r] as u64 % MD;
                for m in (1..=r).rev() {
                    z = (z + dq[i - 1][m] as u64 * ds[i - 2][m][r] as u64) % MD;
                }
                dq[i][r] = z;
            }
        }
    }
    dr[0] = ds[0][0][n];
    dr[1] = ds[1][0][n];
    for i in 2..=x {
        let mut z = (dr[i - 1] as u64 * ff[i - 2] + ff[i - 1] * dr[i - 2] as u64) % MD;
        for m in 1..n {
            z = (z + dq[i - 1][m] as u64 * dp[i - 2][m] as u64) % MD;
        }
        dr[i] = z;
    }
    println!("{}", dr[x]);
}



