// array type
use std::io;

fn init(prime: &mut [i32], prime_list: &mut [i32]) {
    let mut cnt = 0;
    prime[2] = 1;
    prime_list[cnt] = 2;
    cnt += 1;
    for i in (3..1005000).step_by(2) {
        let mut j = 0;
        while j < cnt {
            if i % prime_list[j] == 0 {
                break;
            }
            if (prime_list[j] as i64) * (prime_list[j] as i64) > i as i64 {
                break;
            }
            j += 1;
        }
        if j == cnt || i % prime_list[j] != 0 {
            prime_list[cnt] = i;
            prime[i] = 1;
            cnt += 1;
        }
    }
}
